def shift_scores(A,B,bg):
 h=len(A);w=len(A[0]);
 for d in range(-5,6):
  sc=tot=0
  for r in range(h):
   for c in range(w):
    j=c+d
    if 0<=j<w:
     sc += (A[r][c]!=bg)==(B[r][j]!=bg); tot+=1
  print(d,sc,tot)
