def rowbest(A,B,bg,maxshift=5):
 for i,(a,b) in enumerate(zip(A,B)):
  vals=[]
  for d in range(-maxshift,maxshift+1):
   cols=[c for c in range(len(a)) if 0<=c+d<len(b)]
   sc=sum((a[c]!=bg)==(b[c+d]!=bg) for c in cols)/len(cols)
   vals.append((sc,d))
  print(i,sorted(vals,reverse=True)[:3])
