def fullscore(A,B,bg,d):
 h=len(A);w=len(A[0]);tot=0
 for r in range(h):
  for c in range(w):
   j=c+d
   b=(B[r][j]!=bg) if 0<=j<w else False
   tot += ((A[r][c]!=bg)==b)
 return tot/(h*w)
